271	fn parse_rust_crate_config(
272	    root: &Path,
273	    files: &BTreeMap<String, ParsedFile>,
274	    manifest_hashes: &BTreeMap<String, String>,
275	) -> Option<RustCrateConfig> {
276	    if manifest_hashes.is_empty() {
277	        return Some(RustCrateConfig::from_convention(files));
278	    }
279	
280	    let mut cfg = RustCrateConfig::from_convention(files);
281	    let mut crate_roots = BTreeSet::new();
282	    let mut workspace_members = BTreeSet::new();
283	    let mut bin_paths = BTreeSet::new();
284	    let mut parsed_any = false;
285	    let mut editions_seen: BTreeSet<u16> = BTreeSet::new();
286	
287	    // Collect EVERY discovered `[workspace.package] edition` (not just a last-wins
288	    // scalar): prism collects all `Cargo.toml` repo-wide into one `manifest_hashes`,
289	    // so a repo may hold multiple workspace roots on opposite anchoring sides. The
290	    // full set drives the recall-safe second uniformity term (§2.2); a representative
291	    // scalar resolves the `{ workspace = true }` value form.
292	    let mut workspace_editions: BTreeSet<u16> = BTreeSet::new();
293	    let mut workspace_edition: Option<u16> = None;
294	    for manifest_path in manifest_hashes.keys() {
295	        let abs = root.join(manifest_path);
296	        let Ok(text) = std::fs::read_to_string(&abs) else {
297	            continue;
298	        };
299	        let Ok(value) = text.parse::<toml::Value>() else {
300	            continue;
301	        };
302	        if let Some(ed) = value
303	            .get("workspace")
304	            .and_then(|w| w.get("package"))
305	            .and_then(|p| p.get("edition"))
306	            .and_then(|e| e.as_str())
307	            .and_then(parse_edition)
308	        {
309	            workspace_editions.insert(ed);
310	            workspace_edition = Some(ed);
311	        }
312	    }
313	
314	    // Per-workspace-root `[workspace.dependencies]` pre-scan (BLOCKER 2): a repo can
315	    // hold MULTIPLE workspace roots, so a global name->target map would cross-resolve
316	    // a same-named workspace dep into the wrong workspace. Key the map by the
317	    // workspace-root dir (the dir that declared `[workspace]`), and record the set of
318	    // workspace-root dirs so each member resolves through its OWNING (nearest-ancestor)
319	    // workspace. Only entries carrying a `path` (the in-repo workspace-dep targets) are
320	    // recorded; targets are normalized (`..`/`.` collapsed) to the manifest-dir form.
321	    let mut workspace_dep_paths: BTreeMap<String, BTreeMap<String, String>> = BTreeMap::new();
322	    let mut workspace_root_dirs: BTreeSet<String> = BTreeSet::new();
323	    for manifest_path in manifest_hashes.keys() {
324	        let abs = root.join(manifest_path);
325	        let Ok(text) = std::fs::read_to_string(&abs) else {
326	            continue;
327	        };
328	        let Ok(value) = text.parse::<toml::Value>() else {
329	            continue;
330	        };
331	        let manifest_dir = manifest_path
332	            .strip_suffix("Cargo.toml")
333	            .unwrap_or("")
334	            .trim_end_matches('/');
335	        // A manifest that declares `[workspace]` is a workspace root (members and/or
336	        // `[workspace.dependencies]` hang off it).
337	        let ws = value.get("workspace");
338	        if ws.is_some() {
339	            workspace_root_dirs.insert(manifest_dir.to_string());
340	        }
341	        if let Some(ws_deps) = ws
342	            .and_then(|w| w.get("dependencies"))
343	            .and_then(|d| d.as_table())
344	        {
345	            let entry = workspace_dep_paths
346	                .entry(manifest_dir.to_string())
347	                .or_default();
348	            for (name, spec) in ws_deps {
349	                if let Some(path) = spec.get("path").and_then(|p| p.as_str()) {
350	                    // Skip an out-of-repo workspace-dep target (a `..` that escapes the
351	                    // repo root): `normalize_repo_rel` returns `None` (re-review BLOCKER A).
352	                    if let Some(target) = normalize_repo_rel(&join_manifest_rel(manifest_dir, path))
353	                    {
354	                        entry.insert(name.clone(), target);
355	                    }
356	                }
357	            }
358	        }
359	    }
360	    let mut member_in_repo_deps: BTreeMap<String, BTreeMap<String, String>> = BTreeMap::new();
361	
362	    for manifest_path in manifest_hashes.keys() {
363	        let abs = root.join(manifest_path);
364	        let Ok(text) = std::fs::read_to_string(&abs) else {
365	            continue;
366	        };
367	        let Ok(value) = text.parse::<toml::Value>() else {
368	            continue;
369	        };
370	        parsed_any = true;
371	        let manifest_dir = manifest_path
372	            .strip_suffix("Cargo.toml")
373	            .unwrap_or("")
374	            .trim_end_matches('/');
375	
376	        if value.get("package").is_some() {
377	            // Cargo default: a `[package]` with no `edition` key is edition 2015.
378	            let pkg_ed = value.get("package").and_then(|p| p.get("edition"));
379	            let edition = pkg_ed
380	                .and_then(|e| e.as_str())
381	                .and_then(parse_edition)
382	                .or_else(|| {
383	                    // `edition = { workspace = true }` -> the workspace root edition.
384	                    if pkg_ed
385	                        .and_then(|e| e.get("workspace"))
386	                        .and_then(|w| w.as_bool())
387	                        .unwrap_or(false)
388	                    {
389	                        workspace_edition
390	                    } else {
391	                        None
392	                    }
393	                })
394	                .unwrap_or(2015);
395	            cfg.edition = edition;
396	            editions_seen.insert(edition);
397	        }
398	
399	        // Every `[package]` manifest's dir IS a concrete workspace-member dir. Record
400	        // those (NOT the `[workspace].members` patterns) so the member-dir derivations
401	        // that prefix-match `workspace_members` (`lib_root_member_dir`,
402	        // `crate_name_for_root`) work on GLOB workspaces like ruff
403	        // (`members = ["crates/*"]`), where a raw `crates/*` pattern never prefix-matches
404	        // a concrete root path (`crates/ruff_db/src/lib.rs`). prism has already walked
405	        // every member's `Cargo.toml` into `manifest_hashes`, so their dirs ARE the
406	        // expanded member set; the declared patterns are redundant for this purpose.
407	        if value.get("package").is_some() && !manifest_dir.is_empty() {
408	            workspace_members.insert(manifest_dir.to_string());
409	        }
410	
411	        if let Some(path) = value
412	            .get("lib")
413	            .and_then(|l| l.get("path"))
414	            .and_then(|p| p.as_str())
415	        {
